package api.robot_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class RobotControllerTest { @Mock RobotService service; @InjectMocks RobotController controller; @Test @DisplayName("UT-BE-ROBOT-CTRL-001 로봇 목록을 조회한다") void list(){ List<RobotDTO>x=List.of(); when(service.list()).thenReturn(x); assertThat(controller.list()).isSameAs(x); } @Test @DisplayName("UT-BE-ROBOT-CTRL-002 로봇 상세를 조회한다") void detail(){ RobotDTO x=new RobotDTO(); when(service.detail(1)).thenReturn(x); assertThat(controller.detail(1)).isSameAs(x); } @Test @DisplayName("UT-BE-ROBOT-CTRL-003 로봇 상태를 수정한다") void state(){ RobotDTO d=new RobotDTO(); when(service.updateState(1,d)).thenReturn(1); assertThat(controller.updateState(1,d)).isEqualTo(1); } @Test @DisplayName("UT-BE-ROBOT-CTRL-004 로봇 점검을 완료한다") void maintenance(){ when(service.completeMaintenance(1)).thenReturn(1); assertThat(controller.completeMaintenance(1)).isEqualTo(1); } @Test @DisplayName("UT-BE-ROBOT-CTRL-005 로봇을 등록한다") void signup(){ RobotDTO d=new RobotDTO(); when(service.signUp(d)).thenReturn(1); assertThat(controller.signUp(d)).isEqualTo(1); } @Test @DisplayName("UT-BE-ROBOT-CTRL-006 로봇을 삭제한다") void delete(){ when(service.delete(1)).thenReturn(1); assertThat(controller.delete(1)).isEqualTo(1); } }
